command:
$files = @(
    'CMakeLists.txt',
    'include\ForgeConductor\Dashboard\DashboardPreparedExchange.h',
    'include\ForgeConductor\Dashboard\DashboardResponseComposer.h',
    'include\ForgeConductor\Dashboard\DashboardSseBroadcaster.h',
    'include\ForgeConductor\Dashboard\DashboardSseFrameEncoder.h',
    'include\ForgeConductor\Dashboard\DashboardStaticAssetStore.h',
    'include\ForgeConductor\Dashboard\DashboardTelemetryJsonCodec.h',
    'include\ForgeConductor\Dashboard\IDashboardAssetStore.h',
    'src\Dashboard\DashboardResponseComposer.cpp',
    'src\Dashboard\DashboardSseBroadcaster.cpp',
    'src\Dashboard\DashboardSseFrameEncoder.cpp',
    'src\Dashboard\DashboardStaticAssetStore.cpp',
    'src\Dashboard\DashboardTelemetryJsonCodec.cpp',
    'tests\Dashboard\DashboardPreparedExchangeTests.cpp',
    'tests\Dashboard\DashboardResponseComposerTests.cpp',
    'tests\Dashboard\DashboardSseBroadcasterTests.cpp',
    'tests\Dashboard\DashboardStaticAssetStoreTests.cpp',
    'tests\Dashboard\DashboardTelemetryJsonCodecTests.cpp',
    '.forge-codex\state\decisions\P16-007-bounded-dashboard-assets-and-sse-publication.md'
)
$utf8 = [Text.UTF8Encoding]::new($false, $true)
foreach ($file in $files) {
    $data = [IO.File]::ReadAllBytes($file)
    if ($data.Length -ge 3 -and $data[0] -eq 0xef -and $data[1] -eq 0xbb -and $data[2] -eq 0xbf) {
        throw "$file contains a UTF-8 BOM."
    }
    $null = $utf8.GetString($data)
    for ($index = 0; $index -lt $data.Length; ++$index) {
        if ($data[$index] -eq 10 -and ($index -eq 0 -or $data[$index - 1] -ne 13)) {
            throw "$file contains a bare LF."
        }
        if ($data[$index] -eq 13 -and ($index + 1 -ge $data.Length -or $data[$index + 1] -ne 10)) {
            throw "$file contains a bare CR."
        }
    }
    if ($data.Length -lt 2 -or $data[$data.Length - 2] -ne 13 -or $data[$data.Length - 1] -ne 10) {
        throw "$file does not end with CRLF."
    }
}
Write-Output "Text policy passed for $($files.Count) files."
